//PrivacyPolicyScreen.tsx

import { getContentMaxWidth, useOrientation } from "@/app/utils/responsive";
import { Ionicons } from "@expo/vector-icons";
import { useNavigation } from "@react-navigation/native";
import React, { useLayoutEffect } from "react";
import {
    ScrollView,
    StyleSheet,
    Text,
    TouchableOpacity,
    View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { useTheme } from "../context/ThemeContext";
import { dynamicSpacing, isTablet, scaleFont } from "../utils/responsive";

export default function PrivacyPolicyScreen(): React.JSX.Element {
  const navigation = useNavigation();
  const { theme } = useTheme();
  const themeColors = theme.colors;
  const { width } = useOrientation();
  const isWide = width >= 768;
  const contentMaxWidth = getContentMaxWidth(isTablet ? 700 : 520);

  useLayoutEffect(() => {
    navigation.setOptions({
      headerTitle: "",
      headerStyle: {
        backgroundColor: themeColors.card,
        elevation: 0,
        shadowColor: "transparent",
        borderBottomWidth: 0,
      },
      headerLeft: () => (
        <TouchableOpacity
          onPress={() => navigation.goBack()}
          hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}
          style={{ flexDirection: "row", alignItems: "center", marginLeft: 10 }}
        >
          <Ionicons
            name="arrow-back"
            size={isTablet ? 35 : 28}
            color={themeColors.text}
          />
          <Text
            style={{
              color: themeColors.text,
              fontFamily: "Montserrat-Regular",
              fontSize: scaleFont(18),
              marginLeft: 5,
            }}
          >
            Einstellungen
          </Text>
        </TouchableOpacity>
      ),
    });
  }, [navigation, themeColors]);

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: themeColors.background }}>
      <ScrollView
        style={{ flex: 1 }}
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
      >
        <Text style={[styles.title, { color: themeColors.text }]}>
          Datenschutzerklärung
        </Text>
        <View
          style={[
            styles.contentWrapper,
            isWide && { maxWidth: contentMaxWidth, alignSelf: "center" },
          ]}
        >
          <Text style={[styles.sectionTitle, { color: themeColors.text }]}>
            1. Kontakt
          </Text>
          <Text style={[styles.description, { color: themeColors.text }]}>
            Skilt GP1 SHK wird von Skilt Studio betrieben. Bei Fragen zur App
            oder zum Datenschutz erreichst du uns unter{" "}
            <Text>info@skilt.app</Text>. Weitere Infos findest du auf unserer
            Website: <Text>www.skilt.app</Text>.
          </Text>

          <Text style={[styles.sectionTitle, { color: themeColors.text }]}>
            2. Lokale Datenspeicherung und Offline-Betrieb
          </Text>
          <Text style={[styles.description, { color: themeColors.text }]}>
            Deine Fortschritte und Einstellungen werden ausschließlich auf
            deinem Gerät gespeichert, wodurch die App offline funktioniert. Es
            erfolgt keine Speicherung oder Verarbeitung deiner Daten auf
            externen Servern.
          </Text>

          <Text style={[styles.sectionTitle, { color: themeColors.text }]}>
            3. Keine Datenerhebung oder Weitergabe
          </Text>
          <Text style={[styles.description, { color: themeColors.text }]}>
            Skilt erhebt, verarbeitet und übermittelt keinerlei personenbezogene
            Daten. Es werden keine Tracking- oder Analyse-Tools verwendet, und
            es erfolgt keine Weitergabe an Dritte.
          </Text>

          <Text style={[styles.sectionTitle, { color: themeColors.text }]}>
            4. Verlust der lokalen Daten
          </Text>
          <Text style={[styles.description, { color: themeColors.text }]}>
            Alle Daten werden nur lokal auf deinem Gerät gespeichert. Sie gehen
            verloren, wenn du die App deinstallierst oder die App-Daten löschst.
            In diesem Fall startet die App bei einer erneuten Installation ohne
            gespeicherte Fortschritte.
          </Text>

          <Text style={[styles.sectionTitle, { color: themeColors.text }]}>
            5. App-Updates
          </Text>
          <Text style={[styles.description, { color: themeColors.text }]}>
            Updates für Skilt GP1 SHK werden über den App Store bereitgestellt.
            Diese betreffen ausschließlich die Funktionalität der App und führen
            nicht zur Erhebung oder Verarbeitung von Daten.
          </Text>

          <Text style={[styles.description, { color: themeColors.text }]}>
            Bitte beachte, dass der App Store eigene Datenschutzbestimmungen
            hat, die unabhängig von Skilt gelten. Informationen dazu findest du
            in den Datenschutzhinweisen deines App Stores.
          </Text>

          <View style={{ height: 40 }} />
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  title: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(18),
    fontWeight: "400",
    textAlign: "center",
    paddingVertical: dynamicSpacing(8, 12),
  },
  scrollView: {
    flex: 1,
    paddingHorizontal: dynamicSpacing(22, 30),
    paddingVertical: dynamicSpacing(16, 22),
  },
  scrollContent: {
    flexGrow: 1,
    paddingVertical: dynamicSpacing(16, 22),
    paddingHorizontal: dynamicSpacing(22, 30),
  },
  contentWrapper: {
    width: "100%",
  },
  sectionTitle: {
    fontFamily: "Montserrat-SemiBold",
    fontSize: scaleFont(18),
    marginTop: dynamicSpacing(20, 28),
    marginBottom: dynamicSpacing(8, 12),
  },
  description: {
    fontFamily: "OpenSans-Regular",
    fontSize: scaleFont(16),
    lineHeight: 22,
    marginBottom: dynamicSpacing(16, 22),
  },
});
