// app/screens/Exam/ExamStartScreen.tsx
import { useTheme } from "@/app/context/ThemeContext";
import { demoMissingWord } from "@/app/data/demoMissingWord";
import { demoMultipleChoice } from "@/app/data/demoMultipleChoice";
import {
  dynamicSpacing,
  getContentMaxWidth,
  isTablet,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";
import { useNavigation } from "@react-navigation/native";
import LottieView from "lottie-react-native";
import { useEffect, useState } from "react";
import { ScrollView, StyleSheet, Text, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import NextButton from "../components/NextButton";
import { fetchAllExamResultsWeb } from "../utils/userResultsWeb";
import QuizMissingWordSlide from "./QuizMissingWordSlide";
import QuizMultipleChoiceSlide from "./QuizMultipleChoiceSlide";

export default function ExamStartScreen() {
  const { theme } = useTheme(); // <-- mode raus
  const isDarkMode = theme.dark === true;
  const navigation = useNavigation<any>();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [questions, setQuestions] = useState<any[]>([]);
  const [selectedValue, setSelectedValue] = useState<string | null>(null);
  const [confirmRequested, setConfirmRequested] = useState(false);
  const [quizConfirmed, setQuizConfirmed] = useState(false);
  const [undoElement, setUndoElement] = useState<React.ReactNode | null>(null);

  const [totalScore, setTotalScore] = useState(0);
  const [totalMaxScore, setTotalMaxScore] = useState(0);
  const [allAnswers, setAllAnswers] = useState<any[]>([]);
  const [examStartTime] = useState(Date.now());
  const [loadingDone, setLoadingDone] = useState(false);
  const { width } = useOrientation();
  const isWide = width >= 768;
  const contentMaxWidth = getContentMaxWidth(isTablet ? 700 : 520);
  const backgroundColor = isDarkMode
    ? theme.colors.background // Dark Mode: normales Dark-Theme
    : "#34495e";
  const [examId, setExamId] = useState<number | null>(null);

  // ermittelt automatisch die nächste zu startende Prüfung
  useEffect(() => {
    const determineExamId = async () => {
      try {
        const results = await fetchAllExamResultsWeb();
        const lastExam =
          results.length > 0 ? results[results.length - 1] : null;
        const nextId = lastExam ? lastExam.id + 1 : 1;
        setExamId(nextId);
      } catch (e) {
        console.error("determineExamId ERROR:", e);
        setExamId(1); // Fallback: erste lokale Prüfung
      }
    };

    determineExamId();
  }, []);

  // lädt die Fragen der ermittelten Prüfung
  useEffect(() => {
    if (!examId) return;

    const load = async () => {
      const combined = [...demoMultipleChoice, ...demoMissingWord];
      setQuestions(combined);
      setLoadingDone(true);
    };

    load();
  }, [examId]);

  const handleNext = () => {
    setSelectedValue(null);
    setConfirmRequested(false);
    setQuizConfirmed(false);
    setUndoElement(null);

    if (currentIndex < questions.length - 1) {
      setCurrentIndex((prev) => prev + 1);
    } else {
      const examDuration = Math.round((Date.now() - examStartTime) / 1800);
      navigation.navigate("ExamResult", {
        score: totalScore,
        maxScore: totalMaxScore,
        duration: examDuration,
        answersJSON: JSON.stringify(allAnswers),
        examId: examId,
      });
    }
  };

  const onNextPress = () => {
    if (!quizConfirmed) {
      setConfirmRequested(true);
    } else {
      handleNext();
    }
  };

  const nextText = quizConfirmed ? "Weiter" : "Bestätigen";
  const nextActive = selectedValue !== null;

  if (!loadingDone) {
    return (
      <View
        style={{
          flex: 1,
          backgroundColor,
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <View
          style={{
            transform: [{ translateY: -40 }],
            alignItems: "center",
          }}
        >
          <LottieView
            source={require("../../assets/animations/Loading.json")}
            autoPlay
            loop
            style={{ width: 200, height: 200 }}
          />
          <Text
            style={{
              marginTop: 20,
              fontFamily: "Montserrat-Regular",
              fontSize: scaleFont(18),
              color: "#f5f5f5",
              textAlign: "center",
            }}
          >
            Fragen werden geladen...
          </Text>
        </View>
      </View>
    );
  }
  const currentQuiz = questions[currentIndex];

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor }}>
      <ScrollView
        style={{ flex: 1 }}
        contentContainerStyle={[
          styles.scrollContent,
          isWide && {
            alignItems: "center",
            paddingHorizontal: dynamicSpacing(30, 40),
          },
        ]}
        showsVerticalScrollIndicator={false}
      >
        <View
          style={[
            styles.contentWrapper,
            isWide && { maxWidth: contentMaxWidth, alignSelf: "center" },
            // Phone bleibt unverändert
          ]}
        >
          {/* Zähler oben */}
          <View style={styles.counterRow}>
            <Text style={styles.counterText}>
              {currentIndex + 1}/{questions.length}
            </Text>
          </View>
          {currentQuiz.type === "mc" ? (
            <QuizMultipleChoiceSlide
              quizId={currentQuiz.QuizId}
              selected={selectedValue}
              onSelect={(v) => setSelectedValue(v)}
              confirmRequested={confirmRequested}
              onConfirmed={() => setQuizConfirmed(true)}
              onResult={(correct, total) => {
                setTotalScore((prev) => prev + correct);
                setTotalMaxScore((prev) => prev + total);
                setAllAnswers((prev) => [
                  ...prev,
                  {
                    questionId: currentQuiz.QuizId,
                    questionText:
                      currentQuiz.QuestionText ||
                      currentQuiz.TextTemplate ||
                      "",
                    userAnswer: Array.isArray(selectedValue)
                      ? selectedValue.join(", ")
                      : selectedValue || "",
                    correctAnswer:
                      currentQuiz.type === "mc"
                        ? currentQuiz.CorrectOption || ""
                        : Array.isArray(currentQuiz.CorrectValues)
                          ? currentQuiz.CorrectValues.join(", ")
                          : currentQuiz.CorrectValues || "",
                    options:
                      currentQuiz.type === "mc"
                        ? currentQuiz.Options || currentQuiz.options || []
                        : [],
                    isCorrect: correct > 0,
                  },
                ]);
              }}
            />
          ) : (
            <QuizMissingWordSlide
              quizId={currentQuiz.QuizId}
              selected={selectedValue}
              onSelect={(v) => setSelectedValue(v)}
              confirmRequested={confirmRequested}
              onConfirmed={() => setQuizConfirmed(true)}
              onResult={(correct, total, selections) => {
                setTotalScore((prev) => prev + correct);
                setTotalMaxScore((prev) => prev + total);

                setAllAnswers((prev) => [
                  ...prev,
                  {
                    questionId: currentQuiz.QuizId,
                    questionText: currentQuiz.TextTemplate || "",
                    userAnswer: selections || [],
                    correctAnswer: Array.isArray(currentQuiz.CorrectValues)
                      ? currentQuiz.CorrectValues
                      : [currentQuiz.CorrectValues],
                    type: "missing",
                    isCorrect: correct === total,
                  },
                ]);
              }}
              setUndoElement={setUndoElement}
            />
          )}

          <View style={styles.bottomContainer}>
            <View
              style={{
                flexDirection: "row",
                justifyContent: "center",
                alignItems: "center",
                gap: 16,
                minHeight: 60,
                paddingBottom: dynamicSpacing(30, 40),
              }}
            >
              {undoElement}
              <NextButton
                onPress={onNextPress}
                active={nextActive}
                text={nextText}
              />
            </View>
          </View>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: dynamicSpacing(20, 30),
    justifyContent: "space-between",
  },
  scrollContent: {
    flexGrow: 1,
    justifyContent: "space-between",
    paddingVertical: dynamicSpacing(10, 14),
  },

  contentWrapper: {
    width: "100%",
    justifyContent: "space-between",
    paddingHorizontal: dynamicSpacing(14, 20),
  },
  counterRow: {
    width: "100%",
    alignItems: "flex-end",
    paddingTop: dynamicSpacing(6, 10),
    paddingBottom: dynamicSpacing(6, 10),
  },
  counterText: {
    fontFamily: "Montserrat-Bold",
    fontSize: scaleFont(14),
    color: "#f5f5f5",
  },
  text: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(18),
    textAlign: "center",
  },
  bottomContainer: {
    width: "100%",
    alignItems: "center",
    justifyContent: "flex-end",
    paddingBottom: dynamicSpacing(20, 30),
  },
});
