// ImpressumScreen.tsx

import { Ionicons } from "@expo/vector-icons";
import { useNavigation } from "@react-navigation/native";
import React, { useLayoutEffect } from "react";
import {
    ScrollView,
    StyleSheet,
    Text,
    TouchableOpacity,
    View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { useTheme } from "../context/ThemeContext";
import {
    dynamicSpacing,
    getContentMaxWidth,
    isTablet,
    scaleFont,
    useOrientation,
} from "../utils/responsive";

export default function ImpressumScreen(): React.JSX.Element {
  const navigation = useNavigation();
  const { theme } = useTheme();
  const themeColors = theme.colors;
  const { width } = useOrientation();
  const isWide = width >= 768;
  const contentMaxWidth = getContentMaxWidth(isTablet ? 700 : 520);

  useLayoutEffect(() => {
    navigation.setOptions({
      headerTitle: "",
      headerStyle: {
        backgroundColor: themeColors.card,
        elevation: 0,
        shadowColor: "transparent",
        borderBottomWidth: 0,
      },
      headerLeft: () => (
        <TouchableOpacity
          onPress={() => navigation.goBack()}
          hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}
          style={{ flexDirection: "row", alignItems: "center", marginLeft: 10 }}
        >
          <Ionicons
            name="arrow-back"
            size={isTablet ? 35 : 28}
            color={themeColors.text}
          />
          <Text
            style={{
              color: themeColors.text,
              fontFamily: "Montserrat-Regular",
              fontSize: scaleFont(18),
              marginLeft: 5,
            }}
          >
            Einstellungen
          </Text>
        </TouchableOpacity>
      ),
    });
  }, [navigation, themeColors]);

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: themeColors.background }}>
      <Text style={[styles.title, { color: themeColors.text }]}>Impressum</Text>

      <ScrollView
        style={{ flex: 1, backgroundColor: themeColors.background }}
        contentContainerStyle={[
          styles.scrollContent,
          isWide && {
            alignItems: "center",
            paddingHorizontal: dynamicSpacing(30, 40),
          },
        ]}
        showsVerticalScrollIndicator={false}
      >
        <View
          style={[
            styles.contentWrapper,
            isWide && { maxWidth: contentMaxWidth, alignSelf: "center" },
          ]}
        >
          <Text style={[styles.sectionTitle, { color: themeColors.text }]}>
            Betreiber
          </Text>
          <Text style={[styles.description, { color: themeColors.text }]}>
            Skilt GP1 SHK wird von Skilt Studio betrieben.
          </Text>

          <Text style={[styles.sectionTitle, { color: themeColors.text }]}>
            Verantwortlich für den Inhalt
          </Text>
          <Text style={[styles.description, { color: themeColors.text }]}>
            Rebecca Stelter{"\n"}
            Gubener Str. 36A{"\n"}
            03149 Forst (Lausitz){"\n"}
            Kontakt: info@skilt.app
          </Text>
        </View>

        <View style={{ height: dynamicSpacing(30, 40) }} />
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  title: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(18),
    textAlign: "center",
    paddingVertical: dynamicSpacing(10, 14),
  },
  scrollContent: {
    flexGrow: 1,
    paddingVertical: dynamicSpacing(16, 22),
  },
  contentWrapper: {
    width: "100%",
    paddingHorizontal: dynamicSpacing(22, 30),
  },
  sectionTitle: {
    fontFamily: "Montserrat-SemiBold",
    fontSize: scaleFont(18),
    marginTop: dynamicSpacing(20, 28),
    marginBottom: dynamicSpacing(8, 12),
  },
  description: {
    fontFamily: "OpenSans-Regular",
    fontSize: scaleFont(16),
    lineHeight: 22,
    marginBottom: dynamicSpacing(16, 22),
  },
});
