// app/screens/SubchapterContentScreen.tsx

import { useTheme } from "@/app/context/ThemeContext";
import { Ionicons } from "@expo/vector-icons";
import { useNavigation, useRoute } from "@react-navigation/native";
import type React from "react";
import { useEffect, useState } from "react";
import {
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import NextButton from "../components/NextButton";
import { demoSubchapterContent } from "../data/demoSubchapterContent";
import {
  dynamicSpacing,
  getContentMaxWidth,
  isTablet,
  scaleFont,
  useOrientation,
} from "../utils/responsive";
import ContentSlide from "./ContentSlide";
import QuizAssignSlide from "./QuizAssignSlide";
import QuizDropdownSlide from "./QuizDropdownSlide";
import QuizExplanationSlide from "./QuizExplanationSlide";
import QuizFormulaSlide from "./QuizFormulaSlide";
import QuizTrueFalseSlide from "./QuizTrueFalseSlide";

type ContentItem = {
  ContentType: string;
  RefId?: number | null;
  ContentData?: string | null;
  ImagePath?: string | null;
};

export default function SubchapterContentScreen() {
  const navigation = useNavigation<any>();
  const route = useRoute<any>();
  const { subchapterId, subchapterTitle, chapterId, chapterTitle } =
    route.params || {};

  const { width } = useOrientation();
  const isWide = width >= 768;
  const contentMaxWidth = getContentMaxWidth(520);

  const { theme } = useTheme();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [content, setContent] = useState<ContentItem[]>([]);
  const [quizAnswered, setQuizAnswered] = useState(false);
  const [selectedValue, setSelectedValue] = useState<string | boolean | null>(
    null,
  );
  const [confirmRequested, setConfirmRequested] = useState(false);
  const [quizConfirmed, setQuizConfirmed] = useState(false);
  const [formulaReady, setFormulaReady] = useState(false);
  const [assignReady, setAssignReady] = useState(false);
  const [points, setPoints] = useState(0);
  const [maxPoints, setMaxPoints] = useState(0);
  const [feedbackText, setFeedbackText] = useState("");
  const [undoElement, setUndoElement] = useState<React.ReactNode | null>(null);

  // Quizdaten laden
  useEffect(() => {
    const filtered = demoSubchapterContent.filter(
      (c) => c.SubchapterId === Number(subchapterId),
    );
    setContent(filtered);
  }, [subchapterId]);

  const handleNext = () => {
    setSelectedValue(null);
    setConfirmRequested(false);
    setQuizConfirmed(false);
    setFeedbackText("");

    if (currentIndex < content.length - 1) {
      setCurrentIndex((prev) => prev + 1);
    } else {
      navigation.navigate("OutroScreen", {
        subchapterId,
        chapterId,
        chapterTitle,
        points,
        maxPoints,
      });
    }
  };

  const progress = content.length > 0 ? (currentIndex + 1) / content.length : 0;

  const currentType = content[currentIndex]?.ContentType;
  const isQuiz =
    currentType === "quiz_truefalse" ||
    currentType === "quiz_explanation" ||
    currentType === "quiz_formula" ||
    currentType === "quiz_assign" ||
    currentType === "quiz_missingword" ||
    currentType === "quiz_dropdown";

  const nextText = isQuiz
    ? quizConfirmed
      ? "Weiter"
      : "Bestätigen"
    : "Weiter";

  useEffect(() => {
    if (currentType !== "quiz_assign") {
      setUndoElement(null);
    }
  }, [currentType]);

  // Steuert wann der der bestätigen button aktiv wird für unterschiedliche Quizlogik
  const nextActive =
    currentType === "quiz_formula" ||
    currentType === "quiz_missingword" ||
    currentType === "quiz_dropdown"
      ? quizConfirmed || formulaReady
      : currentType === "quiz_assign"
        ? quizConfirmed || assignReady
        : isQuiz
          ? selectedValue !== null
          : true;

  const onNextPress = () => {
    if (!isQuiz) {
      handleNext();
      return;
    }

    if (!quizConfirmed) {
      setConfirmRequested(true);
    } else {
      handleNext(); // nach Auswertung → weiter
    }
  };

  // Punkte aus Quiz-Slides sammeln
  const handleQuizResult = (correctCount: number, totalCount: number) => {
    setPoints((prev) => prev + correctCount);
    setMaxPoints((prev) => prev + totalCount);
  };

  return (
    <View
      style={[
        styles.screen,
        {
          backgroundColor: isWide ? "#f8f8f8" : theme.colors.background,
          alignItems: isWide ? "center" : undefined,
        },
      ]}
    >
      <ScrollView
        style={{ flex: 1, width: "100%" }}
        contentContainerStyle={[
          styles.scrollContent,
          isWide && { alignItems: "center" },
        ]}
        showsVerticalScrollIndicator={false}
      >
        <View
          style={[
            styles.contentWrapper,
            isWide && {
              maxWidth: contentMaxWidth,
              borderRadius: 16,
              backgroundColor: theme.colors.background,
              paddingVertical: dynamicSpacing(20, 30),
              paddingHorizontal: dynamicSpacing(16, 24),
            },
          ]}
        >
          <View style={styles.headerContainer}>
            <TouchableOpacity
              onPress={() => navigation.goBack()}
              style={styles.closeButton}
            >
              <Ionicons name="close" size={28} color={theme.colors.text} />
            </TouchableOpacity>
            <View style={styles.progressBarContainer}>
              <View
                style={[
                  styles.progressBar,
                  {
                    width: `${progress * 100}%`,
                    backgroundColor: theme.colors.primary,
                  },
                ]}
              />
            </View>
          </View>

          {content.length > 0 && (
            <>
              {content[currentIndex].ContentType === "intro" && (
                <ContentSlide
                  title={subchapterTitle}
                  text={content[currentIndex].ContentData ?? ""}
                  image={content[currentIndex].ImagePath ?? undefined}
                  onNext={handleNext}
                />
              )}

              {content[currentIndex].ContentType === "quiz_truefalse" && (
                <QuizTrueFalseSlide
                  quizId={content[currentIndex].RefId ?? 0}
                  selected={selectedValue as boolean | null}
                  onSelect={(v: boolean) => setSelectedValue(v)}
                  confirmRequested={confirmRequested}
                  onConfirmed={() => {
                    setQuizConfirmed(true);
                    setConfirmRequested(false);
                  }}
                  onResult={handleQuizResult}
                  onFeedback={(text: string) => setFeedbackText(text)}
                />
              )}

              {content[currentIndex].ContentType === "quiz_explanation" && (
                <QuizExplanationSlide
                  quizId={content[currentIndex].RefId ?? 0}
                  selected={selectedValue as string | null}
                  onSelect={(v: string) => setSelectedValue(v)}
                  confirmRequested={confirmRequested}
                  onConfirmed={() => {
                    setQuizConfirmed(true);
                    setConfirmRequested(false);
                  }}
                  onResult={handleQuizResult}
                  onFeedback={(text: string) => setFeedbackText(text)}
                />
              )}

              {content[currentIndex].ContentType === "quiz_formula" && (
                <QuizFormulaSlide
                  quizId={content[currentIndex].RefId ?? 0}
                  selected={selectedValue as string | null}
                  onSelect={(v: string | null) =>
                    setFormulaReady(v === "ready")
                  }
                  confirmRequested={confirmRequested}
                  onConfirmed={() => {
                    setQuizConfirmed(true);
                    setConfirmRequested(false);
                    setFormulaReady(false);
                  }}
                  onResult={handleQuizResult}
                  onFeedback={(text: string) => setFeedbackText(text)}
                />
              )}

              {currentType === "quiz_assign" && (
                <QuizAssignSlide
                  quizId={content[currentIndex].RefId ?? 0}
                  selected={selectedValue as string | null}
                  onSelect={(v: string | null) => setAssignReady(v === "ready")}
                  confirmRequested={confirmRequested}
                  onConfirmed={() => {
                    setQuizConfirmed(true);
                    setConfirmRequested(false);
                    setAssignReady(false);
                  }}
                  onResult={handleQuizResult}
                  onFeedback={(text: string) => setFeedbackText(text)}
                  setUndoElement={setUndoElement}
                />
              )}

              {currentType === "quiz_dropdown" && (
                <QuizDropdownSlide
                  key={content[currentIndex].RefId}
                  quizId={content[currentIndex].RefId ?? 0}
                  selected={selectedValue as string | null}
                  onSelect={(v: string | null) =>
                    setFormulaReady(v === "ready")
                  }
                  confirmRequested={confirmRequested}
                  onConfirmed={() => {
                    setQuizConfirmed(true);
                    setConfirmRequested(false);
                    setFormulaReady(false);
                  }}
                  onResult={handleQuizResult}
                  onFeedback={(text: string) => setFeedbackText(text)}
                />
              )}
            </>
          )}
          <View style={styles.bottomContainer}>
            {isQuiz && (
              <View style={styles.feedbackContainer}>
                <Text
                  style={[styles.feedbackText, { color: theme.colors.text }]}
                >
                  {feedbackText}
                </Text>
              </View>
            )}

            <View
              style={{
                flexDirection: "row",
                justifyContent: "center",
                alignItems: "center",
                gap: 16,
                minHeight: 60,
                paddingBottom: dynamicSpacing(8, 18),
              }}
            >
              {undoElement}
              <NextButton
                onPress={onNextPress}
                active={nextActive}
                text={nextText}
              />
            </View>
          </View>
        </View>
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
  },
  scrollContent: {
    flexGrow: 1,
    alignItems: "center",
    paddingVertical: dynamicSpacing(16, 24),
  },

  contentWrapper: {
    width: "100%",
    alignItems: "center",
  },
  container: {
    flex: 1,
    padding: dynamicSpacing(16, 24),
  },
  headerContainer: {
    flexDirection: "row",
    alignItems: "center",
    marginTop: dynamicSpacing(20, 30),
    marginBottom: dynamicSpacing(8, 14),
    width: "100%",
    paddingHorizontal: dynamicSpacing(10, 16),
  },
  closeButton: {
    padding: dynamicSpacing(6, 10),
    marginRight: dynamicSpacing(10, 14),
  },
  contentContainer: {
    flex: 1,
    justifyContent: "center",
    alignItems: "center",
  },
  progressBar: {
    height: "100%",
    borderRadius: 10,
  },
  progressBarContainer: {
    flex: 1,
    height: dynamicSpacing(18, 24),
    backgroundColor: "#ccc",
    borderRadius: 10,
    overflow: "visible",
  },
  text: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(18),
  },

  nextButton: {
    alignSelf: "center",
    borderRadius: isTablet ? 14 : 12,
    paddingVertical: dynamicSpacing(14, 18),
    paddingHorizontal: dynamicSpacing(40, 56),
  },
  nextButtonText: {
    fontFamily: "Montserrat-Bold",
    fontSize: scaleFont(18),
  },
  bottomContainer: {
    width: "100%",
    alignItems: "center",
    justifyContent: "flex-end",
    paddingBottom: dynamicSpacing(20, 30),
  },
  feedbackContainer: {
    alignItems: "center",
    minHeight: dynamicSpacing(20, 30),
    marginBottom: dynamicSpacing(10, 20),
  },
  feedbackText: {
    fontFamily: "Montserrat-Regular",
    fontSize: scaleFont(18),
  },
  footer: {
    width: "100%",
    borderTopWidth: 1,
    alignItems: "center",
    justifyContent: "center",
    paddingVertical: dynamicSpacing(16, 22),
    paddingHorizontal: dynamicSpacing(20, 26),
  },

  footerRow: {
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
    gap: 16,
    minHeight: 60,
  },
});
