// app/Training/QuizFormulaSlide.tsx

import { useTheme } from "@/app/context/ThemeContext";
import {
  dynamicSpacing,
  isTablet,
  scaleFont,
  useOrientation,
} from "@/app/utils/responsive";
import { useEffect, useState } from "react";
import type { DemoQuizFormula as QuizFormula } from "../data/demoFormula";
import { demoQuizFormula } from "../data/demoFormula";

import {
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import MathJaxSvg from "react-native-mathjax-svg";

interface QuizFormulaSlideProps {
  quizId: number;
  selected: string | null;
  onSelect: (v: string | null) => void;
  confirmRequested: boolean;
  onConfirmed: () => void;
  onResult: (correctCount: number, totalCount: number) => void;
  onFeedback: (text: string) => void;
}

export default function QuizFormulaSlide({
  quizId,
  selected,
  onSelect,
  confirmRequested,
  onConfirmed,
  onResult,
  onFeedback,
}: QuizFormulaSlideProps) {
  const { theme } = useTheme();
  const [quiz, setQuiz] = useState<QuizFormula | null>(null);
  const [formula, setFormula] = useState("");
  const [feedback, setFeedback] = useState("");
  const [filledValues, setFilledValues] = useState<string[]>([]);
  const { width } = useOrientation();
  const isWide = width >= 768;

  useEffect(() => {
    const data = demoQuizFormula.find((q) => q.QuizId === quizId);
    if (!data) return;

    setQuiz(data);
    setFormula(data.Formula);
    setFilledValues([]);
    setFeedback("");
    onSelect(null);
  }, [quizId]);

  useEffect(() => {
    if (confirmRequested && quiz) {
      const expected = quiz.CorrectValues.reduce(
        (acc: string, v: string) => acc.replace("\\square", `{${v}}`),
        quiz.Formula,
      );

      const correctValues = quiz.CorrectValues;
      let correctCount = 0;
      filledValues.forEach((v, i) => {
        if (v === correctValues[i]) correctCount++;
      });

      const isAllCorrect = correctCount === correctValues.length;
      const isPartial = correctCount > 0 && correctCount < correctValues.length;

      let message = "";
      if (isAllCorrect) message = "✅ Richtig!";
      else if (isPartial) message = "⚡ Fast!";
      else message = "❌ Falsch";

      setFeedback(message);
      onFeedback(message);

      onResult(correctCount, correctValues.length);
      onConfirmed();
    }
  }, [confirmRequested]);

  const handleSelect = (val: string) => {
    const nextIndex = filledValues.length;
    if (nextIndex < CorrectValues.length) {
      const newValues = [...filledValues, val];
      setFilledValues(newValues);

      let newFormula = Formula;
      newValues.forEach((v) => {
        newFormula = newFormula.replace("\\square", `{${v}}`);
      });
      setFormula(newFormula);

      // ✅ jetzt im Block, Zugriff auf newValues möglich
      onSelect(newValues.length === CorrectValues.length ? "ready" : null);
    }
  };

  const handleUndo = () => {
    if (filledValues.length === 0) return;
    const newValues = filledValues.slice(0, -1);
    setFilledValues(newValues);

    let newFormula = Formula;
    newValues.forEach((v) => {
      newFormula = newFormula.replace("\\square", `{${v}}`);
    });
    setFormula(newFormula);

    // 👇 Meldung an den Parent (Button deaktivieren, falls nicht mehr alles ausgefüllt)
    onSelect(newValues.length === CorrectValues.length ? "ready" : null);
  };

  if (!quiz || !quiz.Options) return null;

  const { CorrectValues, Formula } = quiz;

  return (
    <ScrollView
      contentContainerStyle={[
        styles.container,
        {
          backgroundColor: theme.colors.background,
          flexGrow: 1,
          paddingTop: isWide ? dynamicSpacing(12, 16) : dynamicSpacing(32, 28),
          paddingBottom: isWide
            ? dynamicSpacing(20, 28)
            : dynamicSpacing(36, 44),
        },
      ]}
      showsVerticalScrollIndicator={false}
    >
      <Text style={[styles.question, { color: theme.colors.text }]}>
        {quiz.QuestionText}
      </Text>

      <View
        style={[
          styles.formulaContainer,
          {
            width: "100%",
            maxWidth: isWide ? 520 : 360,
            marginBottom: dynamicSpacing(30, 40),
          },
        ]}
      >
        <MathJaxSvg
          fontSize={scaleFont(isWide ? 10 : 8)}
          color={theme.colors.text}
          style={{
            width: "100%",
            transform: [{ scale: isWide ? 1 : 0.85 }],
          }}
        >
          {formula}
        </MathJaxSvg>
      </View>

      <View style={styles.optionsContainer}>
        {quiz.Options.map((opt: string, i: number) => (
          <TouchableOpacity
            key={i}
            style={[
              styles.optionButton,
              {
                minHeight: dynamicSpacing(44, 48),
                paddingVertical: dynamicSpacing(8, 10),
                paddingHorizontal: dynamicSpacing(10, 12),
              },

              (() => {
                let bgColor = theme.colors.card;
                let borderColor = theme.colors.border;
                let borderWidth = 1.5;

                const isSelected = filledValues.includes(opt);
                const isCorrectOpt = quiz.CorrectValues.includes(opt);

                if (!feedback) {
                  if (isSelected) {
                    bgColor = theme.colors.card;
                    borderColor = "#d1d1d1";
                    borderWidth = 2;
                  }
                } else {
                  if (isSelected && isCorrectOpt) {
                    bgColor = "#4CAF5020";
                    borderColor = "#4CAF50";
                    borderWidth = 2;
                  } else if (isSelected && !isCorrectOpt) {
                    bgColor = "#E5393520";
                    borderColor = "#E53935";
                    borderWidth = 2;
                  } else if (isCorrectOpt && !isSelected) {
                    bgColor = theme.colors.card;
                    borderColor = "#4CAF50";
                  }
                }

                return { backgroundColor: bgColor, borderColor, borderWidth };
              })(),
            ]}
            onPress={() => handleSelect(opt)}
            disabled={feedback !== ""}
          >
            <MathJaxSvg
              fontSize={scaleFont(isWide ? 9 : 7)}
              color={theme.colors.text}
              style={{
                transform: [{ scale: isWide ? 1 : 0.85 }],
              }}
            >
              {opt}
            </MathJaxSvg>
          </TouchableOpacity>
        ))}
      </View>

      {!feedback && (
        <TouchableOpacity
          onPress={handleUndo}
          disabled={filledValues.length === 0}
          style={styles.undoButton}
        >
          <Text
            style={[
              styles.undoIcon,
              {
                color:
                  filledValues.length > 0 ? theme.colors.primary : "#a0a0a0",
              },
            ]}
          >
            ⌫
          </Text>
        </TouchableOpacity>
      )}
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: {
    flexGrow: 1,
    justifyContent: "flex-start",
    alignItems: "center",
    paddingHorizontal: dynamicSpacing(20, 30),
    paddingTop: dynamicSpacing(60, 50),
    paddingBottom: dynamicSpacing(80, 100),
  },
  question: {
    fontFamily: "Lato-Bold",
    fontSize: scaleFont(20),
    textAlign: "center",
    marginBottom: dynamicSpacing(40, 48),
  },
  formulaContainer: {
    marginBottom: dynamicSpacing(40, 50),
    alignItems: "center",
    justifyContent: "center",
  },
  optionsContainer: {
    width: "90%",
    gap: dynamicSpacing(16, 22),
  },
  optionButton: {
    paddingVertical: dynamicSpacing(16, 22),
    borderRadius: isTablet ? 14 : 12,
    alignItems: "center",
    borderWidth: 1.5,
  },
  feedback: {
    marginTop: dynamicSpacing(30, 40),
    fontFamily: "Montserrat-SemiBold",
    fontSize: scaleFont(18),
  },
  undoButton: {
    marginTop: dynamicSpacing(12, 16),
    padding: dynamicSpacing(10, 14),
    borderRadius: isTablet ? 14 : 12,
    backgroundColor: "transparent",
  },
  undoIcon: {
    fontSize: scaleFont(24),
    color: "#d1d1d1", // oder theme.colors.primary, wenn du magst
  },
});
